svg.script:
const loops = [...document.querySelectorAll('g')].filter(g => /^m\d+$/.test(g.id)).map(g => ({ frames: [...g.children], at: -1 }));
const still = matchMedia('(prefers-reduced-motion: reduce)');
let start = null;
function tick(now) {
  start ??= now;
  const frame = still.matches ? 59 : Math.floor((now - start) * 18 / 1000);
  for (const loop of loops) {
    const i = frame % loop.frames.length;
    if (i === loop.at) continue;
    if (loop.at >= 0) loop.frames[loop.at].setAttribute('display', 'none');
    loop.frames[i].removeAttribute('display');
    loop.at = i;
  }
  requestAnimationFrame(tick);
}
requestAnimationFrame(tick);
